"""REVIEW COMPUTATION for TASK-20260923-635c5c (J2, J5).

A literal implementation of the definitions and the D2/D3 rules of
AMD-EXP-AUXIN-7e2e3d-20260923-d1d10 (sha256 dfda9030...e5e5), written by the
red team from the amendment text alone. It is NOT the experiment's code and
imports nothing from experiments/EXP-AUXIN-7e2e3d/. It runs no Cheon
algorithm and generates no [x^i]P: it is integer and real arithmetic on
divisors only.

Path A = mpmath at DPS digits. Path B = Python decimal at DPS digits.
Clause references are to the amendment field paths.
"""
import math
from decimal import Decimal, getcontext

import mpmath

DPS = 160                        # definitions.precision: >= 150 digits
mpmath.mp.dps = DPS
getcontext().prec = DPS

BOUNDARY_TOL = mpmath.mpf(10) ** -45   # definitions.bins
TIE_REL = mpmath.mpf(10) ** -100       # definitions.minimiser_and_ties
FLOOR_TOL = mpmath.mpf(10) ** -45      # change.D2_typed_costs.floor_invariant
PATH_TOL = mpmath.mpf(10) ** -50       # definitions.precision (A vs B)


# ---------------------------------------------------------------- integers
def isqrt(n):
    return math.isqrt(n)


def icbrt(n):
    """largest x with x^3 <= n (definitions.integer_functions)"""
    if n < 0:
        raise ValueError
    if n < 8:
        return 1 if n else 0
    # integer Newton from an upper bound (2^ceil(bits/3) >= cbrt(n)); the
    # iterates decrease monotonically to floor(cbrt(n)). (An earlier version
    # seeded from a 53-bit float and fixed up by unit steps, which is
    # correct but unusably slow when the float error is large; it was only
    # ever called on exact cubes below 2^130 before this fix.)
    x = 1 << ((n.bit_length() + 2) // 3)
    while True:
        y = (2 * x + n // (x * x)) // 3
        if y >= x:
            break
        x = y
    while x ** 3 > n:
        x -= 1
    while (x + 1) ** 3 <= n:
        x += 1
    return x


def divisors_from_fact(fact):
    ds = [1]
    for p, e in sorted(fact.items()):
        ds = [d * p ** k for d in ds for k in range(e + 1)]
    return sorted(ds)


def m_of(branch, r):
    return r - 1 if branch == "minus" else r + 1


# ---------------------------------------------------------------- path A
def T_A(branch, m, d):
    m, d = mpmath.mpf(m), mpmath.mpf(d)
    return mpmath.sqrt(m / d) + (mpmath.sqrt(d) if branch == "minus" else d)


def e_A(branch, r, d):
    return mpmath.log(T_A(branch, m_of(branch, r), d), 2) / mpmath.log(r, 2)


def F_A(branch, r):
    L = mpmath.log(r, 2)
    if branch == "minus":
        return (1 + mpmath.log(r - 1, 2) / 4) / L
    return (mpmath.log(3, 2) - mpmath.mpf(2) / 3 + mpmath.log(r + 1, 2) / 3) / L


def C_A(branch, r):
    return mpmath.log(mpmath.sqrt(m_of(branch, r)) + 1, 2) / mpmath.log(r, 2)


# ---------------------------------------------------------------- path B
_LN2 = Decimal(2).ln()


def _log2_dec(x):
    return Decimal(x).ln() / _LN2


def T_B(branch, m, d):
    m, d = Decimal(m), Decimal(d)
    return (m / d).sqrt() + (d.sqrt() if branch == "minus" else d)


def e_B(branch, r, d):
    return _log2_dec(T_B(branch, m_of(branch, r), d)) / _log2_dec(r)


def F_B(branch, r):
    L = _log2_dec(r)
    if branch == "minus":
        return (1 + _log2_dec(r - 1) / 4) / L
    return (_log2_dec(3) - Decimal(2) / 3 + _log2_dec(r + 1) / 3) / L


def C_B(branch, r):
    return _log2_dec(Decimal(m_of(branch, r)).sqrt() + 1) / _log2_dec(r)


# ---------------------------------------------------------------- bins
def bin_of(s):
    """definitions.bins. Returns (bin, boundary_flag)."""
    q1, q3 = mpmath.mpf(1) / 4, mpmath.mpf(3) / 4
    if abs(s - q1) < BOUNDARY_TOL:
        return "NEAR_CEILING", True          # lower-depth side of 1/4
    if abs(s - q3) < BOUNDARY_TOL:
        return "INTERMEDIATE", True          # lower-depth side of 3/4
    if s >= q3:
        return "NEAR_FLOOR", False
    if s <= q1:
        return "NEAR_CEILING", False
    return "INTERMEDIATE", False


def depth(e, C, F):
    return (C - e) / (C - F)


def _float_T(branch, m, d):
    # prefilter only; the reported values are recomputed on paths A and B
    a = math.sqrt(m / d) if m.bit_length() < 1000 else math.exp(0.5 * (math.log(m) - math.log(d)))
    b = math.sqrt(d) if branch == "minus" else float(d)
    return a + b


def branch_minimum(branch, r, candidates):
    """Minimum of e_b over an explicit candidate divisor set, with the
    tie rule of definitions.minimiser_and_ties. Returns a dict."""
    m = m_of(branch, r)
    for d in candidates:
        assert m % d == 0, "candidate is not a divisor"
    fl = {d: _float_T(branch, m, d) for d in candidates}
    fmin = min(fl.values())
    shortlist = [d for d in candidates if fl[d] <= fmin * (1 + 1e-9)]
    eA = {d: e_A(branch, r, d) for d in shortlist}
    emin = min(eA.values())
    tied = sorted(d for d in shortlist if abs(eA[d] - emin) <= TIE_REL * abs(emin))
    dmin = tied[0]
    eB = e_B(branch, r, dmin)
    return {
        "minimiser": dmin,
        "tied": tied,
        "e_A": emin,
        "e_B": eB,
        "path_agree": abs(mpmath.mpf(str(eB)) - emin) <= PATH_TOL,
        "n_candidates": len(candidates),
        "shortlist_size": len(shortlist),
    }


def evaluate_branch(branch, r, status, fact=None, F_part=None, C_part=None):
    """change.D3_descriptive_bins, literally.
    status EXACT: fact = complete factorization of m_b (dict).
    status BOUND: F_part = certified factored part (dict), C_part = the
    composite cofactor C_b = m_b / F_b (int)."""
    m = m_of(branch, r)
    FA, CA = F_A(branch, r), C_A(branch, r)
    FB, CB = F_B(branch, r), C_B(branch, r)
    out = {"branch": branch, "status": status, "bits_r": r.bit_length()}
    if status == "EXACT":
        ds = divisors_from_fact(fact)
        assert math.prod(p ** e for p, e in fact.items()) == m
        cand = ds
    elif status == "BOUND":
        Fb = math.prod(p ** e for p, e in F_part.items())
        assert Fb * C_part == m and C_part > 1
        dF = divisors_from_fact(F_part)
        cand = sorted(set(dF) | {d * C_part for d in dF})   # W_b
        out["W_b_size"] = len(cand)
    else:
        raise ValueError(status)
    bm = branch_minimum(branch, r, cand)
    s = depth(bm["e_A"], CA, FA)
    sB = depth(mpmath.mpf(str(bm["e_B"])), mpmath.mpf(str(CB)), mpmath.mpf(str(FB)))
    out.update({
        "minimiser": bm["minimiser"],
        "minimiser_bits": bm["minimiser"].bit_length(),
        "tied": bm["tied"],
        "e_A": bm["e_A"], "e_B": bm["e_B"], "path_agree": bm["path_agree"],
        "F": FA, "C": CA, "depth": s,
        "depth_path_agree": abs(sB - s) <= PATH_TOL,
        "floor_invariant_ok": bm["e_A"] >= FA - FLOOR_TOL,
    })
    if branch == "plus":
        out["log2_2d"] = mpmath.log(2 * bm["minimiser"], 2)
        out["T_plus_ge_d"] = T_A("plus", m, bm["minimiser"]) >= bm["minimiser"]
    if status == "EXACT":
        b, flag = bin_of(s)
        out.update({"exponent": bm["e_A"], "bin": b, "boundary_flag": flag})
    else:
        # values_by_status BOUND: upper bound = min over W_b, lower bound = F
        out.update({"upper_bound": bm["e_A"], "lower_bound": FA})
        # bin_by_status BOUND
        q3 = mpmath.mpf(3) / 4
        d3_rule = "NEAR_FLOOR" if s >= q3 else "UNDETERMINED"
        bw, flag = bin_of(s)
        out.update({
            "bin": d3_rule,
            "bin_at_least": None if d3_rule == "NEAR_FLOOR" else bw,
            "boundary_flag": flag,
            # latent clause conflict: bins says lower-depth side inside the
            # 1e-45 band above 3/4, D3 says NEAR_FLOOR for depth >= 3/4
            "clause_conflict": bool(flag and s >= q3),
        })
    # secondary metric: bits of the largest divisor of m_b not exceeding isqrt(r)
    lim = isqrt(r)
    below = [d for d in cand if d <= lim]
    out["largest_div_le_isqrt_r_bits"] = max(below).bit_length()
    return out


def fmt(x, digits=40):
    if isinstance(x, (mpmath.mpf,)):
        return mpmath.nstr(x, digits)
    if isinstance(x, Decimal):
        return format(x, "." + str(digits) + "g")
    if isinstance(x, bool) or x is None or isinstance(x, (int, str)):
        return x
    if isinstance(x, list):
        return [fmt(v, digits) for v in x]
    return str(x)


def jsonable(d, digits=40):
    return {k: fmt(v, digits) for k, v in d.items()}

