"""PTM-C: uniformly random 256-bit primes, sampler and seed declared in
ptm_c_declaration.json (sha256 41e69cde...a024, 2026-09-23T21:56:59Z) before
any sample was drawn. Each r - 1 and r + 1 is factored by a review pipeline
under a 120 s cap, then the amendment's D3 status / witness-set / bin rules
are applied unchanged. REVIEW COMPUTATION; no RUN-*, no Cheon, no [x^i]P."""
import json
import math
import random
import signal
import sys
import time
from concurrent.futures import ProcessPoolExecutor

import sympy
from sympy.ntheory import factor_
from sympy.ntheory.ecm import _ecm_one_factor

DECL = json.load(open("ptm_c_declaration.json"))
SEED = DECL["SEED"]
BITS = DECL["bit_size"]
N = DECL["sample_size"]
CAP = 120.0
SMALL = list(sympy.primerange(2, 1 << 20))


def sample():
    rng = random.Random(SEED)
    mr = random.Random(SEED + 1)
    out, drawn = [], 0
    while len(out) < N:
        x = rng.getrandbits(BITS) | (1 << (BITS - 1)) | 1
        drawn += 1
        if sympy.isprime(x) and all(pow(mr.randrange(2, x - 1), x - 1, x) == 1 for _ in range(30)):
            out.append(x)
    return out, drawn


class Cap(Exception):
    pass


def _alarm(sig, frm):
    raise Cap()


def factor_capped(n):
    t0 = time.monotonic()
    primes = {}
    m = n
    for p in SMALL:
        if p * p > m:
            break
        if m % p == 0:
            e = 0
            while m % p == 0:
                m //= p
                e += 1
            primes[p] = e
    queue = [m] if m > 1 else []
    left = []
    current = None
    signal.signal(signal.SIGALRM, _alarm)
    signal.setitimer(signal.ITIMER_REAL, CAP)
    capped = False
    try:
        while queue:
            current = queue.pop()
            N_ = current
            if N_ == 1:
                current = None
                continue
            if sympy.isprime(N_):
                primes[N_] = primes.get(N_, 0) + 1
                current = None
                continue
            pp = sympy.perfect_power(N_)
            if pp:
                b, e = pp
                queue.extend([b] * e)
                current = None
                continue
            f = factor_.pollard_rho(N_, max_steps=300000)
            if not f:
                f = factor_.pollard_pm1(N_, B=10 ** 6)
            if not f:
                for B1 in (2000, 11000, 50000, 250000, 1000000, 3000000):
                    try:
                        f = _ecm_one_factor(N_, B1, 100 * B1, max_curve=50, seed=B1)
                    except ValueError:
                        f = None
                    if f and 1 < f < N_:
                        break
                    f = None
            if not f:
                left.append(N_)
                current = None
                continue
            queue.extend([f, N_ // f])
            current = None
    except Cap:
        capped = True
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
    rest = list(queue) + ([current] if current is not None else []) + left
    comps = []
    for x in rest:
        if x == 1:
            continue
        if sympy.isprime(x):
            primes[x] = primes.get(x, 0) + 1
        else:
            comps.append(x)
    assert math.prod(p ** e for p, e in primes.items()) * math.prod(comps) == n
    return {"n": n, "primes": primes, "composites_left": comps,
            "capped": capped, "seconds": round(time.monotonic() - t0, 2)}


def job(args):
    idx, br, r = args
    m = r - 1 if br == "minus" else r + 1
    return idx, br, factor_capped(m)


if __name__ == "__main__":
    t0 = time.time()
    rs, drawn = sample()
    print(json.dumps({"stage": "sampled", "drawn": drawn, "utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}), file=sys.stderr)
    jobs = [(i, br, r) for i, r in enumerate(rs) for br in ("minus", "plus")]
    res = {}
    with ProcessPoolExecutor(max_workers=DECL["workers"]) as ex:
        for idx, br, fr in ex.map(job, jobs):
            res[(idx, br)] = fr
    from amd_rules import evaluate_branch, jsonable
    rows = []
    for i, r in enumerate(rs):
        row = {"index": i, "r": r, "r_bits": r.bit_length()}
        for br in ("minus", "plus"):
            fr = res[(i, br)]
            if not fr["composites_left"]:
                ev = evaluate_branch(br, r, "EXACT", fact=fr["primes"])
            else:
                ev = evaluate_branch(br, r, "BOUND", F_part=fr["primes"],
                                     C_part=math.prod(fr["composites_left"]))
            row[br] = {"factoring": {"primes": {str(k): v for k, v in fr["primes"].items()},
                                     "composites_left": fr["composites_left"],
                                     "n_composite_parts": len(fr["composites_left"]),
                                     "capped": fr["capped"], "seconds": fr["seconds"]},
                       "eval": jsonable(ev, 30)}
        rows.append(row)
    tally = {}
    for br in ("minus", "plus"):
        t = {}
        for row in rows:
            ev = row[br]["eval"]
            key = ev["status"] + "/" + ev["bin"] + ("" if ev.get("bin_at_least") in (None, "None") else "(at_least " + ev["bin_at_least"] + ")")
            t[key] = t.get(key, 0) + 1
        tally[br] = t
    multi = sum(1 for row in rows for br in ("minus", "plus") if row[br]["factoring"]["n_composite_parts"] > 1)
    checks = {
        "all_path_agree": all(row[br]["eval"]["path_agree"] and row[br]["eval"]["depth_path_agree"] for row in rows for br in ("minus", "plus")),
        "all_floor_invariant_ok": all(row[br]["eval"]["floor_invariant_ok"] for row in rows for br in ("minus", "plus")),
        "any_boundary_flag": any(row[br]["eval"]["boundary_flag"] for row in rows for br in ("minus", "plus")),
        "any_clause_conflict": any(row[br]["eval"].get("clause_conflict") for row in rows for br in ("minus", "plus")),
        "branches_with_more_than_one_composite_part": multi,
    }
    print(json.dumps({"declaration_sha256": "41e69cde8d41c775ab7683a5c4680cd87802f3c3290c18694f6da7913298a024",
                      "drawn": drawn, "rows": rows, "tally_by_branch": tally, "checks": checks,
                      "wall_seconds": round(time.time() - t0, 1)}, indent=1, default=str))
